## Probe: power, false discoveries, x10 selection, stability, target error; 10 replicates; cost.
source("R/00-model.R")
g <- build_grid(); set.seed(1); t0 <- proc.time()[["elapsed"]]
rows <- do.call(rbind, lapply(seq_len(nrow(g)), function(i) { cc <- g[i, ]; r <- do.call(rbind, replicate(10, one_rep(cc), simplify = FALSE))
  a <- aggregate(cbind(power, false_disc, x10, stability, error = target - truth(cc)) ~ method + penalty, r, mean); cbind(K = cc$K, M = cc$M, conf = cc$conf, a) }))
sec <- (proc.time()[["elapsed"]] - t0) / (10 * nrow(g))
md <- c("# ADJ-10 probes", "", "Generated by `R/01-probes.R`, 10 replicates per cell (noisy). Earlier settings (modification 0.3 with 3600 patients; 0.15 with 1800) made discovery perfect or powerless and were changed before this probe.", "",
  paste("|", paste(names(rows), collapse = " | "), "|"), paste(rep("|---", ncol(rows)), collapse = ""),
  apply(rows, 1, function(r) paste("|", paste(c(r[1:5], sprintf("%.3f", as.numeric(r[-(1:5)]))), collapse = " | "), "|")), "",
  sprintf("Unit cost %.2f s per replicate; %d cells at %d replicates is %.2f core-hours.", sec, nrow(g), N_SIM, nrow(g) * N_SIM * sec / 3600), "")
writeLines(md, "results/probes.md")
